    label: 'Class field theory',
    from: 'GL₁',
    to:   'GLₙ',
    rho:  'z ↦ diag(z, …, z)',
    example: 'Hecke χ on 𝔸×/ℚ× transfers to χ ⊞ ⋯ ⊞ χ on GLₙ.',
    satake: 'Satake (α) ↦ (α, α, …, α) — n copies.',
