];

let active = 'sym';

function draw(){
  svg.innerHTML = '';
  // axis bar
  const baseY = 220;
  const leftX = 110, rightX = W - 110;

  // header text
  const t = SVG('text',{x:W/2, y:30,'text-anchor':'middle','font-size':14, fill:'var(--ink)','font-weight':600});
  t.textContent = 'ρ : ᴸH → ᴸG  (click an arrow to inspect)'; svg.appendChild(t);

  transfers.forEach((tr, i) => {
    const y = 70 + i*55;
    const isActive = tr.id === active;
    const col = tr.id === 'cft' ? 'var(--cyan)' : tr.id === 'bc' ? 'var(--violet)' : 'var(--yellow)';

    // left node (H)
    svg.appendChild(SVG('rect',{x:leftX-44, y:y-16, width:88, height:32, rx:6,
      fill:'var(--panel2)', stroke:isActive?col:'var(--line)','stroke-width':isActive?2:1}));
    const lt = SVG('text',{x:leftX, y:y+5,'text-anchor':'middle','font-size':13, fill:'var(--ink)','font-weight':600});
    lt.textContent = 'ᴸ' + tr.from; svg.appendChild(lt);

    // right node (G)
    svg.appendChild(SVG('rect',{x:rightX-44, y:y-16, width:88, height:32, rx:6,
      fill:'var(--panel2)', stroke:isActive?col:'var(--line)','stroke-width':isActive?2:1}));
    const rt = SVG('text',{x:rightX, y:y+5,'text-anchor':'middle','font-size':13, fill:'var(--ink)','font-weight':600});
    rt.textContent = 'ᴸ' + tr.to; svg.appendChild(rt);

    // arrow
    const arr = SVG('line',{x1:leftX+44, y1:y, x2:rightX-44, y2:y,
      stroke:isActive?col:'var(--mute)','stroke-width':isActive?2:1.2,
      'marker-end':'url(#fc-arrow-' + tr.id + ')'});
    svg.appendChild(arr);

    // arrow marker def
    const defs = SVG('defs');
    const mk = SVG('marker',{id:'fc-arrow-' + tr.id, viewBox:'0 0 10 10', refX:9, refY:5,
      markerWidth:6, markerHeight:6, orient:'auto'});
    mk.appendChild(SVG('path',{d:'M0,0 L10,5 L0,10 z', fill: isActive?col:'var(--mute)'}));
    defs.appendChild(mk); svg.appendChild(defs);

    // label above arrow
    const lbl = SVG('text',{x:(leftX+rightX)/2, y:y-8,'text-anchor':'middle','font-size':12,
      fill: isActive?col:'var(--mute)','font-style':'italic'});
