  const sub = SVG('text',{x:W/2, y:H-18,'text-anchor':'middle','font-size':12, fill:'var(--mute)'});
  sub.textContent = 'cuspidal π on H(𝔸)   ⤳   functorial transfer ρ_*(π) on G(𝔸)';
  svg.appendChild(sub);
}

function update(){
  const tr = transfers.find(t => t.id === active);
  out.textContent =
    'Transfer: ' + tr.label + '\n' +
    '  ᴸ' + tr.from + '  →  ᴸ' + tr.to + '\n' +
    '  ρ:  ' + tr.rho + '\n\n' +
    'On Satake parameters:\n  ' + tr.satake + '\n\n' +
    'Concrete instance: ' + tr.example + '\n\n' +
    'Status: ' + tr.status + '\n\n' +
    'L-function identity: L(s, π_H, r ∘ ρ) = L(s, ρ_*(π_H), r) for every r : ᴸG → GL(V).';
}
draw(); update();
